INSERT INTO "Card" ("id", "outputId", "title", "column", "order", "pattern", "content", "figureLayout", "heightBudget", "validation", "generatedLatex", "slideNotes", "table", "figures", "sourceIds", "grounding") VALUES ('card_muamm3cr_kpc2wf', 'out_poster_muamm3cr_lppk', 'Introduction', 1, 0, 'bullets', 'The ability to accurately model latent dynamics is critical in modern robotic environments. In this paper, we explore a novel approach for combining hindsight relabeling with continuous reinforcement learning. Our results indicate substantial improvements on both sample efficiency and final asymptotic performance.', 'single', NULL, 'valid', NULL, NULL, '{"rows":[],"caption":"","hasHeader":false}', '[]', '["asset_txt_1"]', NULL) ON CONFLICT DO NOTHING;
