INSERT INTO "Card" ("id", "outputId", "title", "column", "order", "pattern", "content", "figureLayout", "heightBudget", "validation", "generatedLatex", "slideNotes", "table", "figures", "sourceIds", "grounding") VALUES ('card_muamm3cr_v7l34c', 'out_paper_muamm3cr_fi0p', 'Abstract', NULL, 0, 'section', 'We present a robust method for continuous latent dynamics using hindsight relabeling. We evaluate our approach on 6 demanding robotic manipulation tasks, demonstrating a 28% relative improvement in sample efficiency.', 'single', NULL, 'valid', NULL, NULL, '{"rows":[],"caption":"","hasHeader":false}', '[]', '["asset_txt_1"]', NULL) ON CONFLICT DO NOTHING;
INSERT INTO "Card" ("id", "outputId", "title", "column", "order", "pattern", "content", "figureLayout", "heightBudget", "validation", "generatedLatex", "slideNotes", "table", "figures", "sourceIds", "grounding") VALUES ('card_muamm3cr_yc7x2n', 'out_paper_muamm3cr_fi0p', 'Lagrangian Formulation', NULL, 1, 'section-two-figures', 'In addition to standard RL, our physics-informed prior utilizes Lagrangian mechanics to constrain the learned latent space:

$ \\frac{d}{dt} \\left( \\frac{\\partial \\mathcal{L}}{\\partial \\dot{q}} \\right) - \\frac{\\partial \\mathcal{L}}{\\partial q} = Q_{nc} $

This ensures the decoded trajectories are physically plausible even in low-data regimes. [@reyes2026]', 'single', NULL, 'valid', NULL, NULL, '{"rows":[],"caption":"","hasHeader":false}', '[{"id":"fig_mock_2a","url":"/api/workspaces/demo_ws/assets/fig_mock_2a.png","caption":"Robot joint configuration"},{"id":"fig_mock_2b","url":"/api/workspaces/demo_ws/assets/fig_mock_2b.png","caption":"Latent space visualization"}]', '["asset_eq_1"]', NULL) ON CONFLICT DO NOTHING;
INSERT INTO "Card" ("id", "outputId", "title", "column", "order", "pattern", "content", "figureLayout", "heightBudget", "validation", "generatedLatex", "slideNotes", "table", "figures", "sourceIds", "grounding") VALUES ('card_muamm3cr_qxowxz', 'out_paper_muamm3cr_fi0p', 'Architecture', NULL, 2, 'section-figure', 'The system is composed of an RSSM with a CNN backbone.', 'single', NULL, 'valid', NULL, NULL, '{"rows":[],"caption":"","hasHeader":false}', '[{"id":"fig_mock_p3","url":"/api/workspaces/demo_ws/assets/fig_mock_p3.png","caption":"Model Architecture"}]', '[]', NULL) ON CONFLICT DO NOTHING;
