INSERT INTO "DocumentChunk" ("id", "workspaceId", "documentId", "heading", "content", "tokens", "embedding", "kind", "createdAt", "contextPrefix", "chunkType", "ordinal", "pageStart", "pageEnd", "chapter", "section", "subsection", "sectionPath", "sourceElementIds", "parentChunkId", "previousChunkId", "nextChunkId", "characterCount", "oversized", "contentHash", "parserVersion", "chunkerVersion", "embeddingModelVersion", "schemaVersion", "tokenEstimatorVersion", "embeddingDimensions", "indexVersion") VALUES ('chk-0cea0cdc8e6b2af23ce7d605', 'attention-is-all-you-need', 'doc_transformer_2017', 'Abstract [5/12]', 'Aligning the positions to steps in computation time, they generate a sequence of hidden states ht, as a function of the previous hidden state ht−1 and the input for position t. This inherently sequential nature precludes parallelization
within training examples, which becomes critical at longer sequence lengths, as memory constraints limit batching across examples. Recent work has achieved significant improvements in computational efficiency through factorization tricks [21] and conditional computation [32], while also improving model performance in case of the latter. The fundamental constraint of sequential computation, however, remains. Attention mechanisms have become an integral part of compelling sequence modeling and transduc-
tion models in various tasks, allowing modeling of dependencies without regard to their distance in the input or output sequences [2, 19].', 245, '[-0.028614596,0.06548387,0.036196407,0.024510428,-0.03666404,-0.0048898035,-0.017089121,0.051459473,-0.025002232,0.0026384771,0.019922461,0.06315024,0.044721488,-0.0328524,0.023976913,-0.022030802,0.02902935,0.07538954,-0.14545736,-0.0008848611,-0.02246848,-0.058294363,-0.012434471,-0.015114519,-0.0049819998,0.036639895,-0.021923501,-0.0060457545,0.11280714,-0.12117003,0.03027462,0.10169451,0.048766043,-0.012752649,-0.0100573795,0.07375169,-0.042731937,-0.004984757,-0.0095958775,0.01895286,-0.060929026,0.040417053,-0.01874481,-0.04384941,0.0038078355,-0.11621705,0.009074188,-0.011990523,-0.17390583,-0.051151935,-0.01875056,-0.05204689,-0.024238808,0.011213654,-0.008415051,-0.031713955,0.04812004,0.023022203,0.009466037,-0.03482546,0.010491664,-0.019678017,-0.095756635,-0.027256485,0.050619427,-0.019097721,0.049602278,-0.0148336515,0.022708261,0.15357384,0.004294172,-0.0064417566,-0.06877268,-0.050309893,-0.002167151,0.007675177,0.06385051,0.046600547,0.047401242,-0.10120374,0.0897088,-0.062362548,-0.0151242,0.027178433,-0.0069737704,0.0025112529,-0.019019596,-0.062024552,0.058276173,-0.08109778,0.07177121,-0.026346326,-0.05650766,0.030449044,0.045659002,0.015799958,0.018562283,0.001034497,0.023554245,0.13973622,-0.06263903,0.02976392,-0.0447071,7.375598e-05,0.03336942,-0.011645899,0.031383745,-0.028919397,-0.076495335,0.017490666,-0.008940054,0.0025129989,-0.033776477,0.022113966,0.022403637,-0.06661881,0.03686938,-0.006269057,0.011723751,0.025083512,-0.03538906,0.0031449422,0.05034916,-0.008797044,0.074805476,-0.13733356,-0.07869688,-0.074584946,-0.06820627,-0.078183845,0.10092393,-0.030873457,0.031494264,0.0024328856,0.013660025,0.015556129,0.05448843,-0.08323606,-0.060699508,0.0266432,-0.019420715,0.093983635,0.1035696,0.046466257,0.040754102,0.08325659,-0.02406729,-0.05296622,0.05810693,-0.012683923,-0.02036917,-0.104