INSERT INTO "DocumentChunk" ("id", "workspaceId", "documentId", "heading", "content", "tokens", "embedding", "kind", "createdAt", "contextPrefix", "chunkType", "ordinal", "pageStart", "pageEnd", "chapter", "section", "subsection", "sectionPath", "sourceElementIds", "parentChunkId", "previousChunkId", "nextChunkId", "characterCount", "oversized", "contentHash", "parserVersion", "chunkerVersion", "embeddingModelVersion", "schemaVersion", "tokenEstimatorVersion", "embeddingDimensions", "indexVersion") VALUES ('chk-a273b31ebda13d076c5421de', 'attention-is-all-you-need', 'doc_transformer_2017', 'Abstract [6/12]', 'In all but a few cases [27], however, such attention mechanisms are used in conjunction with a recurrent network. In this work we propose the Transformer, a model architecture eschewing recurrence and instead relying entirely on an attention mechanism to draw global dependencies between input and output. The Transformer allows for significantly more parallelization
and can reach a new state of the art in translation quality after being trained for as little as twelve hours on eight P100 GPUs. 2 Background The goal of reducing sequential computation also forms the foundation of the Extended Neural GPU [16], ByteNet [18] and ConvS2S [9], all of which use convolutional neural networks as basic building block, computing hidden representations in parallel for all input and output positions.', 222, '[-0.0081152655,0.009463564,0.00038285292,0.0055079875,-0.042979874,0.01779472,-0.04255388,-0.00035465966,0.020730583,-0.033033356,-0.018131653,0.023932882,0.05241307,-0.033081036,0.0063041556,-0.033730906,0.049721148,0.07577372,-0.046831217,-0.0014314401,0.011129738,-0.043758485,-0.030370988,0.0031800857,-0.030669533,0.027351152,-0.026801443,-0.04214956,0.050210338,-0.110250235,0.020814769,0.06408155,0.07549026,-0.008952318,-0.053927135,0.027340531,-0.026219862,0.020428238,-0.028804228,0.04271955,-0.086282745,0.07255435,0.0073452843,0.00113845,-0.00633063,-0.06998077,-0.08282663,-0.008041241,-0.10310783,-0.06880723,-0.014352169,-0.057095073,-0.04628328,0.060061384,-0.022792218,-0.0839893,0.06199198,0.040293984,0.04404632,-0.043617383,0.041783236,-0.05168382,-0.06867539,-0.0136951385,-0.029992709,-0.044184946,0.0029773463,-0.005019588,0.0153704,0.10729553,-0.035322674,0.027145822,-0.08738861,-0.051177118,0.016948504,0.022007838,0.04284424,0.028714525,0.07325097,-0.118245214,0.08169151,-0.047788374,-0.050687876,0.002847746,0.048125688,0.037121233,-0.003613192,-0.023181768,0.013688401,-0.09756154,0.059422318,-0.035032995,-0.028803539,0.025420927,0.060719274,-0.04313664,0.014217137,-0.078359894,0.018439434,0.14534666,-0.008563036,0.02757222,-0.028389854,-0.012239085,0.0146158645,-0.008990242,0.016157845,-0.021209538,-0.054488756,0.005220702,-0.02405851,-0.020615486,-0.06921694,0.059193037,0.041543424,-0.083343625,0.0011684316,-0.026588213,0.021064777,0.024485895,-0.021574479,-0.016363017,0.04894269,-0.03251469,0.05219956,-0.112257585,-0.0548