INSERT INTO "DocumentChunk" ("id", "workspaceId", "documentId", "heading", "content", "tokens", "embedding", "kind", "createdAt", "contextPrefix", "chunkType", "ordinal", "pageStart", "pageEnd", "chapter", "section", "subsection", "sectionPath", "sourceElementIds", "parentChunkId", "previousChunkId", "nextChunkId", "characterCount", "oversized", "contentHash", "parserVersion", "chunkerVersion", "embeddingModelVersion", "schemaVersion", "tokenEstimatorVersion", "embeddingDimensions", "indexVersion") VALUES ('chk-d4d087dffd7e8e655aa08622', 'attention-is-all-you-need', 'doc_transformer_2017', 'Abstract [7/12]', 'In these models, the number of operations required to relate signals from
two arbitrary input or output positions grows in the distance between positions, linearly for ConvS2S and logarithmically for ByteNet. This makes it more difficult to learn dependencies between distant positions [ 12]. In the Transformer this is reduced to a constant number of operations, albeit at the cost of reduced effective resolution due to averaging attention-weighted positions, an effect we counteract with Multi-Head Attention as described in section 3.2. Self-attention, sometimes called intra-attention
is an attention mechanism relating different positions of a single sequence in order to compute a representation of the sequence.', 200, '[-0.024045011,0.054227542,0.048459116,0.038264643,-0.029833259,-0.023031285,0.05017646,0.0399803,0.050295148,0.025988936,0.046650685,0.06298849,0.07185037,-0.013427273,0.0044813724,0.016848734,0.054077826,0.053885333,-0.07871738,0.039390042,0.022171356,-0.064615756,0.00674391,-0.057385784,0.0021728138,0.013961765,-0.044858415,-0.053022504,0.0500805,-0.05857006,0.07117032,0.10912692,0.14907536,-0.02451124,-0.078692295,0.03510317,-0.035624333,0.013043531,-0.007850788,0.015985202,-0.05828795,0.08892549,-0.05974523,-0.0370733,0.0069070477,-0.06147189,-0.031850766,0.010680558,-0.13850899,0.0026606717,-0.023172023,-0.02884293,-0.0383912,0.017116312,-0.017760724,-0.039945588,0.056938503,0.038383648,0.001713808,0.015583212,0.052849155,0.004310719,-0.080232985,-0.017492702,0.022904513,-0.00949036,0.039149437,-0.025311092,-0.024581395,0.12526017,0.00062822,-0.012196161,0.004973891,-0.09094086,0.013467763,-0.028580232,0.035734896,0.018690275,0.10036887,-0.10901593,0.08391875,-0.024986,-0.04132523,0.010726034,-0.04107808,0.022633523,0.046399042,0.03482308,0.044283655,-0.08123339,0.04276169,0.013979864,-0.051647242,0.026895192,0.008920132,-0.005530934,0.0012606963,-0.058782313,0.051020846,0.17466484,-0.030202892,0.012012981,-0.050231528,0.0040801987,-0.006089456,-0.037043568,0.06869365,-0.03173027,-0.11833533,0.09005595,-0.053091742,-0.047359504,-0.061614558,0.04191735,0.0002450013,-0.017370349,0.0643907,0.00020591177,0.06361597,-0.0183617,-0.023292856,0.0043734633,0.027962346,0.043418117,0.10429638,-0.12327222,-0.08041677,-0.0046609025,-0.09797887,-0.0901968,0.032799453,-0.059154887,-0.03449844,0.018295819,-0.011349034,0.05896865,0.035313193,-0.028724188,-0.010667698,0.016805785,0.0095983585,0.11141905,0.1140618,0.04874978,-0.0055304207,0.09374521,-0.002054374,-0.05563994,0.052615657,-0.021511717,-0.0154350605,-0.104270644,0.07056408,-0.05570