INSERT INTO "DocumentChunk" ("id", "workspaceId", "documentId", "heading", "content", "tokens", "embedding", "kind", "createdAt", "contextPrefix", "chunkType", "ordinal", "pageStart", "pageEnd", "chapter", "section", "subsection", "sectionPath", "sourceElementIds", "parentChunkId", "previousChunkId", "nextChunkId", "characterCount", "oversized", "contentHash", "parserVersion", "chunkerVersion", "embeddingModelVersion", "schemaVersion", "tokenEstimatorVersion", "embeddingDimensions", "indexVersion") VALUES ('chk-5515c42c0833c364384ba007', 'attention-is-all-you-need', 'doc_transformer_2017', 'Abstract [8/12]', 'Self-attention has been used successfully in a variety of tasks including reading comprehension, abstractive summarization, textual entailment and learning task-independent sentence representations [4, 27, 28, 22]. End-to-end memory networks are based on a recurrent attention mechanism instead of sequence- aligned recurrence and have been shown to perform well on simple-language
question answering and language modeling tasks [34]. To the best of our knowledge, however, the Transformer is the first transduction model relying entirely on self-attention to compute representations of its input and output without using sequence- aligned RNNs or convolution. In the following sections, we will describe the Transformer, motivate self-attention and discuss its advantages over models such as [17, 18] and [9].', 225, '[-0.012712652,0.029124185,-0.0031046004,0.0074934377,-0.028815472,-0.028052133,0.025796708,0.088466614,-0.049031906,-0.0027254433,-0.024634628,0.033593614,0.029914424,0.010751352,0.077262096,-0.028825572,0.042776536,0.011006784,-0.13169011,-0.008963342,-0.046823785,-0.051705,-0.0023093019,0.011000821,-0.03430959,-0.0023231504,-0.043029197,-0.03228479,0.06269658,-0.068701014,0.045188893,0.08816505,0.095162295,-0.0042304113,-0.037512302,0.07645171,-0.03514644,0.0068744463,-0.033153974,0.00024014337,-0.03266616,0.022155853,0.01417688,-0.007786704,-0.013210141,-0.022723915,0.0019706085,-0.013896857,-0.102554455,-0.059748963,-0.028480439,-0.063681364,-0.05375276,0.023690136,-0.009803318,-0.025286583,0.008816306,0.03322612,-0.021250388,-0.030428253,-0.007748524,-0.048198096,-0.115776464,0.059467375,0.04930351,-0.03613839,0.024647957,-0.02392636,-0.018547358,0.09138209,-0.019204415,0.019472376,-0.022001734,-0.013862275,0.015350479,-0.00519914,0.051096544,0.025249448,0.040473975,-0.12756272,0.08559446,-0.039972275,0.0145407105,0.08621674,0.007132418,-0.026327085,-0.0029257736,-0.030581832,-0.008735053,-0.09359024,0.022026343,-0.031779997,-0.0041008987,0.024837092,0.025218764,0.02338867,-0.008893386,-0.008713534,-0.011028183,0.16124798,-0.057559397,0.059424628,0.02402781,-0.029498812,0.014982162,-0.022600992,0.00894675,0.012236036,-0.04261566,0.010977517,-0.016255721,-0.0076912683,-0.053925816,-0.03276707,-0.004177451,-0.0855281,0.065301806,-0.02292455,0.0038403196,0.012522713,0.018925453,-0.021936303,0.04307674,0.0153559735,0.06257382,-0.1184489