INSERT INTO "DocumentChunk" ("id", "workspaceId", "documentId", "heading", "content", "tokens", "embedding", "kind", "createdAt", "contextPrefix", "chunkType", "ordinal", "pageStart", "pageEnd", "chapter", "section", "subsection", "sectionPath", "sourceElementIds", "parentChunkId", "previousChunkId", "nextChunkId", "characterCount", "oversized", "contentHash", "parserVersion", "chunkerVersion", "embeddingModelVersion", "schemaVersion", "tokenEstimatorVersion", "embeddingDimensions", "indexVersion") VALUES ('chk-0444fa03529c3c3f78777fa5', 'attention-is-all-you-need', 'doc_transformer_2017', '[38, 2, 9]. [1/12]', '• The encoder contains self-attention layers. In a self-attention layer all of the keys, values and queries come from the same place, in this case, the output of the previous layer in the encoder. Each position in the encoder can attend to all positions in the previous layer of the encoder. • Similarly, self-attention layers in the decoder allow each position in the decoder to attend to all positions in the decoder up to and including that position. We need to prevent leftward information flow in
the decoder to preserve the auto-regressive property. We implement this inside of scaled dot-product attention by masking out (setting to −∞) all values in the input of the softmax which correspond to illegal connections. See Figure 2.', 205, '[0.020744184,0.07292722,-0.03891595,0.012188082,-0.012695795,0.048064016,0.08954786,0.0046839397,-0.06362615,0.033985026,0.08755637,-0.017888194,0.110168085,-0.00041987302,0.07463958,0.015250751,-0.036537178,0.112869635,-0.1251836,-0.028249687,0.011456208,-0.06823902,-0.02642982,-0.00725115,-0.06480024,0.007535616,-0.08636757,-0.050357476,0.04002262,-0.08816721,0.052124392,-6.700487e-05,0.055041756,0.041877944,0.0024766526,0.052126512,-0.020833097,0.028142631,-0.025989614,0.02102452,-0.07592792,0.041930296,-0.057602618,0.0037883562,0.008037786,-0.053509004,-0.00048544523,0.016313238,-0.093166664,-0.10045147,-0.05094362,-0.027740037,-0.0277801,0.077329494,-0.034832247,-0.022655128,0.049315467,0.01310832,0.0034273686,-0.014734938,0.03938777,-0.052328847,-0.14382267,0.02957338,0.034043375,0.008077911,0.057392385,-0.026946167,-0.054224193,0.122059315,0.050865907,-0.007906103,-0.01869714,-0.052661248,0.056100313,0.006954084,0.006896996,0.0046915207,0.0019428104,-0.06900116,0.056339078,-0.007453074,0.017277217,0.03376714,-0.041346245,0.040355388,-2.024046e-05,0.0037200404,-0.027300755,-0.033820048,0.019250754,-0.04787348,-0.064156234,0.030537827,0.014257552,-0.04155698,-0.029614314,-0.011873464,0.06272435,0.09196878,-0.035682637,0.009454286,-0.054722704,0.008523434,0.042551,-0.011002083,0.028073749,-0.010526541,-0.040903848,0.042272724,-0.02796531,0.004257445,-0.04745089,0.011097995,0.057111684,-0.07703876,0.018700013,-0.01925824,0.054187056,0.032955073,0.010137387,0.016891358,-0.00910892,0.098226115,0.12511538,-0.08856211,-0.010586535,-0.01751979,-0.044491228,-0.021645712,0.047995273,-0.045617558,-0.031049585,0.047001407,-0.03794494,0.0076608863,-0.030533338,-0.0038751399,0.0008585578,-0.014483575,-0.047007225,0.14418764,0.13092344