INSERT INTO "DocumentChunk" ("id", "workspaceId", "documentId", "heading", "content", "tokens", "embedding", "kind", "createdAt", "contextPrefix", "chunkType", "ordinal", "pageStart", "pageEnd", "chapter", "section", "subsection", "sectionPath", "sourceElementIds", "parentChunkId", "previousChunkId", "nextChunkId", "characterCount", "oversized", "contentHash", "parserVersion", "chunkerVersion", "embeddingModelVersion", "schemaVersion", "tokenEstimatorVersion", "embeddingDimensions", "indexVersion") VALUES ('chk-4e2c20e8335a9060d47fac5a', 'attention-is-all-you-need', 'doc_transformer_2017', '[38, 2, 9]. [6/12]', '4 Why Self-Attention In this section we compare various aspects of self-attention layers to the recurrent and convolu- tional layers commonly used for mapping one variable-length sequence
of symbol representations (x1, ..., xn) to another sequence of equal length (z1, ..., zn), with xi, zi ∈ Rd, such as a hidden layer in a typical sequence transduction encoder or decoder. Motivating our use of self-attention we consider three desiderata. One is the total computational complexity per layer. Another is the amount of computation that can be parallelized, as measured by the minimum number of sequential operations required. The third is the path length between long-range dependencies in
the network. Learning long-range dependencies is a key challenge in many sequence transduction tasks.', 220, '[-0.021753982,0.0037332373,0.015692808,-0.011102171,-0.04309451,-0.026655745,0.036629904,-0.014343765,-0.04873397,0.064706594,0.08716691,-0.021185206,0.084114276,-0.05223327,0.0049426993,0.002535679,0.020561947,0.006610507,-0.10953026,0.044757206,0.049799513,-0.08345411,-0.019073093,-0.044908933,0.037227448,0.011561811,0.0044652433,-0.02052529,0.0560468,-0.06415613,0.043145396,0.14581962,0.06026657,-0.021502184,-0.011652168,0.05482055,-0.058990184,-0.030248862,-0.024129646,0.06704695,-0.022193363,0.078388795,0.0038035065,-0.009850971,0.01815326,-0.050070226,-0.00017733822,0.0029558449,-0.101211995,-0.005883168,-0.03838541,0.0055914945,-0.013142177,0.041876175,-0.02259548,-0.047264233,0.035577867,0.04909383,-0.009821668,-0.0016437931,0.055393506,0.011388268,-0.115999915,0.020274876,0.04420417,-0.06865739,0.044206984,-0.03220823,0.01768214,0.12471112,0.010426358,-0.03881163,-0.07837019,-0.061699126,-0.028792435,0.0029510823,0.12108102,0.034289476,-0.0079081105,-0.11017386,0.05609776,0.0026547888,0.01779929,-0.0072240136,0.03819922,0.020427965,-0.040308025,-0.019636435,0.0074707186,-0.089880295,0.07198498,0.016964395,-0.019537158,0.019590063,0.059373915,0.0104206335,-0.006740206,-0.024511736,0.006550127,0.14542481,-0.08092002,0.07044085,0.00024296914,-0.0070692208,-0.008014953,0.018761797,0.08185126,0.004624861,-0.010553198,0.034905232,-0.061813205,-0.0042843907,-0.01622453,-0.009013459,0.04891099,-0.03430658,0.00071480137,-0.020650243,0.033458266,0.034266,-0.05959955,-0.014059052,0.032543346,-0.024982836,0.082410045,-0.13426186,-0.07438879,-0.07643345,-0.04824813,-0.00227755,0.04295503,0.0051605315,-0.02163282,0.08193197,0.0109415,0.033287503,0.035602506,-0.027449768,-0.07537511,0.05323787,-0.042928126,0.0973438,0.108176894,0.055831637,0.034623638,0.02840316,-0.059144605,-0.02714895,0.015763773,-0.08386536,-0.022479123,-0.1315405,0.026740938,-0.039312575,0.031