INSERT INTO "DocumentChunk" ("id", "workspaceId", "documentId", "heading", "content", "tokens", "embedding", "kind", "createdAt", "contextPrefix", "chunkType", "ordinal", "pageStart", "pageEnd", "chapter", "section", "subsection", "sectionPath", "sourceElementIds", "parentChunkId", "previousChunkId", "nextChunkId", "characterCount", "oversized", "contentHash", "parserVersion", "chunkerVersion", "embeddingModelVersion", "schemaVersion", "tokenEstimatorVersion", "embeddingDimensions", "indexVersion") VALUES ('chk-80c7227d6e4c4acf2a222f13', 'attention-is-all-you-need', 'doc_transformer_2017', '[38, 2, 9]. [8/12]', 'In terms of computational complexity, self-attention layers are faster than recurrent layers when the sequence 6 length n is smaller than the representation dimensionality d, which is most often the case with sentence representations used by state-of-the-art models in machine
translations, such as word-piece [38] and byte-pair [31] representations. To improve computational performance for tasks involving very long sequences, self-attention could be restricted to considering only a neighborhood of size r in the input sequence centered around the respective output position. This would increase the maximum path length to O(n/r). We plan to investigate this approach further in future work. A single convolutional layer with kernel width k < n does not connect all pairs of input
and output positions.', 224, '[0.033474464,0.037567507,0.011847952,-0.0040078973,-0.083286904,-0.016433982,-0.022229422,0.023111647,-0.0047459677,-0.025120221,0.016757566,0.04804021,0.06954546,-0.048847184,0.005069532,-0.028682698,0.057355665,0.068233065,-0.10822883,-0.0017031946,0.019213319,-0.04969921,0.0068582348,-0.04615198,0.026341693,0.011815247,-0.034430914,-0.029293895,0.06926573,-0.10087567,0.053827852,0.10960054,0.105706625,-0.0014011551,-0.009976622,0.062384732,-0.015412278,-0.0003928618,0.015250071,0.043294217,-0.07894979,0.08237436,-0.009128867,0.038065735,0.008751016,-0.06704219,-0.03499377,-0.017396426,-0.13837422,-0.065636955,-0.09232668,-0.064397715,-0.049965717,0.020069882,0.0097351605,-0.041342795,0.043918017,0.0040457575,0.0025224288,-0.016794454,0.037028626,-0.03499343,-0.07949436,-0.008948892,0.033232436,-0.029597646,0.06554867,-0.01699243,-0.008813255,0.1440765,-0.026422188,0.0029195072,-0.07862606,-0.069277026,-0.003564642,0.008757625,0.030864853,0.015209584,0.07035738,-0.13447197,0.08293319,-0.0039140787,-0.048776668,0.010579099,-0.029024392,-0.0052984706,-0.0056178533,0.045429513,0.00760483,-0.07736383,0.061928898,-0.020339722,-0.08552471,0.055284187,0.0145182535,-0.030397462,-0.004546104,-0.04320026,0.031054627,0.15804471,-0.05680129,0.020056657,-0.060019787,0.001885504,-0.010629171,0.01583402,0.027210368,0.012746236,-0.07197567,0.034033027,-0.027458314,-0.010832475,-0.0444194,0.010604674,0.06912211,-0.053663038,0.054234285,-0.05328398,0.021504693,0.03831147,-0.07577063,0.028592838,-0.005628167,0.02759776,0.10368625,-0.13988549,-0.049266692,-0.03888948,-0.018261768,-0.018201565,0.08113983,0.0009684155,0.03782494,0.061350163,0.02150377,0.007320421,0.046245582,-0.0042368695,-0.03640497,-0.004254556,-0.010677522,0.1318193,0.09816541,0.049866423,0.06279112,0.11438876,-0.07019195,-0.03634848,0.06219344,0.000575302,-0.018698629,-0.106380604,0.057726447,-0.09423619,0.0028653184,0.03474182,-0.025524104,-0.024472836,-0.08512458,-0.04680178,-0.11870