INSERT INTO "DocumentChunk" ("id", "workspaceId", "documentId", "heading", "content", "tokens", "embedding", "kind", "createdAt", "contextPrefix", "chunkType", "ordinal", "pageStart", "pageEnd", "chapter", "section", "subsection", "sectionPath", "sourceElementIds", "parentChunkId", "previousChunkId", "nextChunkId", "characterCount", "oversized", "contentHash", "parserVersion", "chunkerVersion", "embeddingModelVersion", "schemaVersion", "tokenEstimatorVersion", "embeddingDimensions", "indexVersion") VALUES ('chk-3c835ee83b28978c614ea680', 'attention-is-all-you-need', 'doc_transformer_2017', 'EN-DE EN-FR EN-DE EN-FR [3/5]', 'On the WMT 2014 English-to-French
translation task, our big model achieves a BLEU score of 41.0, outperforming all of the previously published single models, at less than 1/4 the training cost of the previous state-of-the-art model. The Transformer (big) model trained for English-to-French used dropout rate Pdrop = 0.1, instead of 0.3. For the base models, we used a single model obtained by averaging the last 5 checkpoints, which were written at 10-minute intervals. For the big models, we averaged the last 20 checkpoints. We used
