INSERT INTO "DocumentChunk" ("id", "workspaceId", "documentId", "heading", "content", "tokens", "embedding", "kind", "createdAt", "contextPrefix", "chunkType", "ordinal", "pageStart", "pageEnd", "chapter", "section", "subsection", "sectionPath", "sourceElementIds", "parentChunkId", "previousChunkId", "nextChunkId", "characterCount", "oversized", "contentHash", "parserVersion", "chunkerVersion", "embeddingModelVersion", "schemaVersion", "tokenEstimatorVersion", "embeddingDimensions", "indexVersion") VALUES ('chk-0198346f23cb357674164cb6', 'attention-is-all-you-need', 'doc_transformer_2017', '0.0 4.67 25.3 [5/6]', 'Our results in Table 4 show that despite the lack of task-specific tuning our model performs sur- prisingly well, yielding better results than all previously reported models with the exception of the Recurrent Neural Network Grammar [8]. In contrast to RNN sequence-to-sequence models [37], the Transformer outperforms the Berkeley- Parser [29] even when training only on the WSJ training set of 40K sentences. 7 Conclusion
In this work, we presented the Transformer, the first sequence transduction model based entirely on attention, replacing the recurrent layers most commonly used in encoder-decoder architectures with multi-headed self-attention. For translation tasks, the Transformer can be trained significantly faster than architectures based on recurrent or convolutional layers.', 220, '[0.033271782,0.0168446,0.007305727,-0.00029911264,-0.027637126,0.029023442,-0.051618375,0.0075134872,-0.010426606,-0.006834108,-0.011322617,0.017033977,0.024999656,0.0068310164,-0.0029350233,-0.025762035,0.061527003,0.030054685,-0.079957046,-0.02771642,-0.039459806,-0.070822336,-0.010792659,0.013481802,0.017195579,0.00507863,-0.08435467,-0.043155704,0.071213916,-0.09939892,-0.018586816,0.051976338,0.039618913,-0.018707747,-0.013772013,0.08034156,-0.039149832,0.0494516,-0.011552665,0.04728008,-0.08282499,0.0011952267,-0.013818421,0.039152812,-0.021475943,-0.03926458,-0.0825542,-0.0366629,-0.16216971,-0.02688797,-0.106019765,-0.048938017,0.01597248,0.028924694,0.043811396,-0.07233865,0.035405036,0.055299673,0.0058429153,0.0054722237,-0.021407219,-0.032051973,-0.10118806,-0.012515803,0.033240378,-3.620899e-05,0.06939634,-0.000120022785,-0.020796293,0.118944,-0.04782979,-0.00090731506,-0.035889897,-0.011227244,-0.0017445218,0.0057631736,-0.010505869,0.032964863,0.054158397,-0.09891135,0.0815423,-0.069130495,-0.026092596,0.00088009494,-0.009192251,-0.03556797,-0.010165569,-0.000335618,0.052640364,-0.030807808,0.03487022,-0.071634725,-0.012697157,0.033377744,-0.021295624,0.022513509,0.016228544,0.037784707,0.010134119,0.1353004,-0.061720937,0.018567106,-0.028692132,-0.0015375725,-0.0393584,-0.0020544524,0.01783465,-0.032836035,-0.05312522,0.024941165,-0.02891098,0.010935518,-0.026447928,-0.01662577,0.015430554,-0.0824811,0.008539222,-0.026522605,0.0073476695,0.09725396,0.01435742,-0.006947383,0.075050004,0.040185437,0.0719538,-0.0981943,-0.037315596,-0.06366148,-0.006912226,-0.082366176,0.10928544,0.01836