INSERT INTO "DocumentChunk" ("id", "workspaceId", "documentId", "heading", "content", "tokens", "embedding", "kind", "createdAt", "contextPrefix", "chunkType", "ordinal", "pageStart", "pageEnd", "chapter", "section", "subsection", "sectionPath", "sourceElementIds", "parentChunkId", "previousChunkId", "nextChunkId", "characterCount", "oversized", "contentHash", "parserVersion", "chunkerVersion", "embeddingModelVersion", "schemaVersion", "tokenEstimatorVersion", "embeddingDimensions", "indexVersion") VALUES ('chk-4a1cbca76fe27470648515e3', 'attention-is-all-you-need', 'doc_transformer_2017', '0.0 4.67 25.3 [6/6]', 'On both WMT 2014 English-to-German and WMT 2014 English-to-French translation tasks, we achieve a new state of the art. In the former task
our best model outperforms even all previously reported ensembles. We are excited about the future of attention-based models and plan to apply them to other tasks. We plan to extend the Transformer to problems involving input and output modalities other than text and to investigate local, restricted attention mechanisms to efficiently handle large inputs and outputs such as images, audio and video. Making generation less sequential is another research goals of ours. The code we used to train and evaluate
our models is available at https://github.com/ tensorflow/tensor2tensor. Acknowledgements We are grateful to Nal Kalchbrenner and Stephan Gouws for their fruitful comments, corrections and inspiration.', 237, '[0.00086628855,0.010206917,0.02177748,-0.0055602933,-0.021954987,-0.034580544,-0.046835706,0.03863497,-0.022670487,0.048659988,0.027401831,-0.027328284,0.053934533,-0.017760884,0.05601652,-0.052374404,0.014224953,0.06428163,-0.09658249,-0.043041732,-0.012193669,-0.09862037,0.042123925,-0.026655722,-0.024333602,-0.015363022,-0.08455657,-0.055708103,0.0943354,-0.06848902,-0.022722399,0.06201014,0.076424934,-0.034865137,-0.0028680277,0.061608225,-0.016981637,-0.03198632,-0.050036058,0.047649305,-0.059259236,0.030114211,0.007872375,0.032377027,-0.0387543,-0.054912366,0.010912737,-0.030099882,-0.1583869,-0.045211058,-0.08334335,-0.06985098,-0.046090703,0.017466366,-0.0033260824,-0.07002983,0.050253857,0.039282616,-0.0034184756,-0.024804922,0.033465218,-0.07421837,-0.11329837,0.034817874,0.018733887,-0.01314365,0.040016904,0.028546715,-0.037787985,0.053387195,-0.0046870196,0.020335047,-0.043787524,0.00077584037,0.022549827,-0.07335716,0.03255644,-0.007823716,0.009306475,-0.102131404,0.11702465,-0.020564044,-0.037475873,0.038278006,-0.015124025,-0.018619843,-0.028813379,0.02944695,0.06375156,-0.04672204,0.017026396,-0.03839712,-0.029244136,0.029085603,0.0029375858,-0.008079235,0.04044882,-0.040551398,0.022018466,0.19553751,-0.03814418,0.027556477,0.032522168,-0.0020337899,0.024844164,-0.03837175,0.002488299,-0.01958634,-0.005513185,-0.00093130267,-0.03352007,-0.03431789,-0.08886819,0.009043287,0.033671092,-0.072535545,0.031049304,-0.021085879,0.058767416,0.016018447,-0.023243451,-0.012054092,0.05303804,0.038878743,0.09001225,-0.118139274,-0.045199245,-0.04239526,-0.011543957,-0.034531336,0.07914377,-0.0128632,0.005580076,0.0117765125,-0.003339587,-0.011790308,0.024457527,-0.08517137,0.0020435455,0.010463257,-0.009846142,0.11009364,0.10097441,0.06969614,0.0059719696,0