INSERT INTO "DocumentChunk" ("id", "workspaceId", "documentId", "heading", "content", "tokens", "embedding", "kind", "createdAt", "contextPrefix", "chunkType", "ordinal", "pageStart", "pageEnd", "chapter", "section", "subsection", "sectionPath", "sourceElementIds", "parentChunkId", "previousChunkId", "nextChunkId", "characterCount", "oversized", "contentHash", "parserVersion", "chunkerVersion", "embeddingModelVersion", "schemaVersion", "tokenEstimatorVersion", "embeddingDimensions", "indexVersion") VALUES ('chk-6de98e7bd41308d30986eaa8', 'bert-pre-training', 'doc_bert_2018', 'Abstract [6/11]', 'Unlike left-to- right language model pre-training, the MLM ob- jective enables the representation to fuse the left and the right context, which allows us to pre- train a deep bidirectional Transformer. In addi- tion to the masked language model, we also use a “next sentence
prediction” task that jointly pre- trains text-pair representations. The contributions of our paper are as follows: • We demonstrate the importance of bidirectional pre-training for language representations. Un- like Radford et al. (2018), which uses unidirec- tional language models for pre-training, BERT uses masked language models to enable pre- trained deep bidirectional representations.', 186, '[-0.0823809,0.03961015,-0.010148589,0.009572222,-0.015568469,0.07355824,-0.07299951,-0.011040577,-0.022037424,-0.034486726,-0.028479733,0.011816288,0.056586333,-0.004512319,0.016914293,-0.056988344,0.0569113,0.06517663,-0.06457694,-0.012392667,0.009200004,0.0016942872,0.09629565,0.027840583,0.0025613443,0.010653784,0.00831644,-0.056923606,0.09639722,-0.088337906,-0.025669085,0.05472202,0.015622744,0.010346845,-0.05507757,0.10488186,0.028347721,0.07453613,-0.030640358,0.039140105,-0.05885647,0.032895237,-0.018474048,0.0696963,-0.00049055426,-0.06052656,-0.050057158,-0.012992892,-0.17723499,-0.03154794,-8.696591e-06,-0.061623745,-0.03305833,-0.008163307,0.004479012,-0.08377642,0.08465206,-0.02903175,0.021804301,-0.026985576,-0.08542102,-0.050603364,-0.098563105,0.103276916,-0.010662939,0.056546822,0.019445442,0.024329368,-0.015210547,0.10053371,-0.050354663,0.026569733,-0.017440954,-0.020426663,0.034100447,0.037601836,0.01665296,0.009894935,0.06620474,-0.1508653,0.14959566,-0.010567623,0.010261537,0.08502922,-0.04605021,0.026807157,0.0020013868,-0.032786656,-0.046666853,-0.08382845,0.012451991,-0.079626374,0.020964384,0.08029753,0.009275179,-0.025733557,-0.047208577,0.011191339,0.049780022,0.15914881,-0.018080564,-0.020632103,0.0040519414,0.03453946,-0.009136352,-0.07195075,0.028773353,-0.058393512,-0.0022119132,-0.0052764663,0.01306131,-0.037841514,-0.056655426,0.010552191,0.0008353582,-0.093838565,0.0666871,-0.03894995,0.033104718,0.045124803,-0.012309325,0.013785315,0.039282832,0.017526617,0.05570791,-0.14862433,-0.051127877,-0.06766349,-0.015922498,-0.07570171,0.0496423