INSERT INTO "DocumentChunk" ("id", "workspaceId", "documentId", "heading", "content", "tokens", "embedding", "kind", "createdAt", "contextPrefix", "chunkType", "ordinal", "pageStart", "pageEnd", "chapter", "section", "subsection", "sectionPath", "sourceElementIds", "parentChunkId", "previousChunkId", "nextChunkId", "characterCount", "oversized", "contentHash", "parserVersion", "chunkerVersion", "embeddingModelVersion", "schemaVersion", "tokenEstimatorVersion", "embeddingDimensions", "indexVersion") VALUES ('chk-89de09ef0b6d514d98e2b253', 'bert-pre-training', 'doc_bert_2018', 'Abstract [7/11]', 'This is also in contrast to Peters et al. (2018a), which uses a shallow concatenation of independently trained
left-to-right and right-to-left LMs. • We show that pre-trained representations reduce the need for many heavily-engineered task- speciﬁc architectures. BERT is the ﬁrst ﬁne- tuning based representation model that achieves state-of-the-art performance on a large suite of sentence-level and token-level tasks, outper- forming many task-speciﬁc architectures. • BERT advances the state of the art for eleven NLP tasks. The code and pre-trained mod- els are available at https://github.com/ google-research/bert. 2 Related Work There is a long history of pre-training general lan- guage representations, and we brieﬂy review the most widely-used approaches in this section.', 218, '[-0.0596804,0.042140238,0.01762963,0.0014323848,-0.05652349,0.022730349,-0.113626316,0.004305605,-0.0152060175,-0.010078247,-0.03860072,0.064412415,0.08825746,-0.027421562,0.02523288,-0.032094833,0.10531862,0.03367433,0.013980806,-0.022266673,0.013748045,-0.05512343,0.033794504,0.0053265314,-0.003290885,0.01864129,-0.013574544,-0.039913706,0.09173147,-0.11680979,-0.0076500815,0.058467846,0.04856713,0.04014276,-0.0069820643,0.09544902,-0.028532937,0.024742156,-0.06762515,0.028537262,-0.02808655,0.031745866,-0.019943777,0.03122184,-0.016627017,-0.050567113,-0.038471915,-0.05708161,-0.18071954,-0.041858025,-0.04995904,-0.045690868,0.019569036,0.04951516,-0.011326025,-0.06373054,0.045316946,0.013656063,-0.011461296,-0.0039215423,-0.020410897,-0.06632359,-0.08199253,0.050694134,-0.007935488,0.07624818,0.05809132,0.0078616785,-0.006871129,0.026404902,-0.087067425,-0.008812196,-0.061003283,0.0033582975,-0.0088642,0.0011653188,0.014369262,0.009356091,0.067898795,-0.0920458,0.14044991,-0.025609214,-0.052643355,0.080230996,0.007327685,-0.0047929157,0.0014417414,-0.04213278,0.011534817,-0.056502838,0.006246899,-0.109078564,-0.019635934,0.04584072,-0.0019682182,-0.027572427,-0.0065761744,-0.0011038698,0.06673781,0.1436919,-0.021820182,-0.0002712541,-0.034997705,-0.03149594,0.008420563,-0.023446806,0.045680493,-