INSERT INTO "DocumentChunk" ("id", "workspaceId", "documentId", "heading", "content", "tokens", "embedding", "kind", "createdAt", "contextPrefix", "chunkType", "ordinal", "pageStart", "pageEnd", "chapter", "section", "subsection", "sectionPath", "sourceElementIds", "parentChunkId", "previousChunkId", "nextChunkId", "characterCount", "oversized", "contentHash", "parserVersion", "chunkerVersion", "embeddingModelVersion", "schemaVersion", "tokenEstimatorVersion", "embeddingDimensions", "indexVersion") VALUES ('chk-712a23469c8f6e3129d949c3', 'bert-pre-training', 'doc_bert_2018', 'Abstract [8/11]', '2.1 Unsupervised Feature-based Approaches Learning widely applicable representations of words has been an active area of research for decades, including non-neural (Brown et al., 1992; Ando and Zhang, 2005; Blitzer et al., 2006) and neural (Mikolov et al., 2013; Pennington et al., 2014) methods. Pre-trained word embeddings are an integral
part of modern NLP systems, of- fering signiﬁcant improvements over embeddings learned from scratch (Turian et al., 2010). To pre- train word embedding vectors, left-to-right lan- guage modeling objectives have been used (Mnih and Hinton, 2009), as well as objectives to dis- criminate correct from incorrect words in left and right context (Mikolov et al., 2013). These approaches have been generalized to coarser granularities, such as sentence embed- dings (Kiros et al., 2015; Logeswaran and Lee, 2018)
or paragraph embeddings (Le and Mikolov, 2014).', 249, '[-0.02755201,0.03535471,0.046448976,0.0385881,-0.0340301,0.018669365,-0.058368307,0.018533299,-0.056743864,-0.028689034,0.031742226,0.042320497,0.05579759,-0.013235446,0.044143233,-0.0025028507,0.014203788,0.08324131,-0.11211218,-0.02815775,-0.020018127,-0.013526784,0.009066919,0.004591971,0.04028362,0.025319487,-0.0069236895,-0.018409016,0.07761568,-0.07336494,-0.0093343705,0.065016486,0.07195605,0.04006259,-0.010132191,0.09205902,-0.032127835,0.06860673,-0.08172077,0.025008673,-0.05186505,-0.026778163,-0.01097063,0.01698957,0.018629503,-0.038397975,-0.013242337,0.00882921,-0.15124832,-0.018673187,0.003200998,-0.056870278,-0.023454538,-0.0032393755,-0.00096052734,-0.06189989,0.014590128,0.045784336,0.005678739,-0.007710645,-0.052279465,-0.019509342,-0.15645182,0.06755046,0.003083154,0.020478439,0.09715876,-0.028384173,-0.028246982,0.110769376,0.04095239,0.00969331,-0.02527648,-0.057969276,-0.032500062,0.043439973,0.054868754,0.01854959,0.014986911,-0.11548425,0.15691255,-0.033054642,-0.018333023,0.038658574,-0.030810477,-0.0060521183,-0.014667605,-0.03110915,-0.037048403,-0.08441651,0.02931542,-0.07144996,0.050825823,0.027869198,0.08197296,-0.00815434,-0.00015274741,-0.012953067,0.00806531,0.11438825,-0.038580045,-0.024405574,-0.006692435,-0.0035442163,0.0030026122,-0.032641362,0.02811474,-0.08276192,-0.022555484,-0.004000395,-0.014145787,-0.01906873,-0.058899153,-0.028515723,0.029129371,-0.089517415,0.056661908,0.023175271,0.035196926,0.061772842,-0.031265706,-0.00060600357,0.11724335,0.05898513,0.06797905,-0.07823828,-0.050977048,-0.06569384,-0.059227154,-0.051460866,0.079363324,-0.013966353,-0.06994512,0.023373151,0.022052374,-0.009092851,0.08409725,-0.10678603,-0.009893721,0.05649123,-0.08045061,0.08273372,0.095678814,0.078436635,0.037554327,0.07168198,0.017272409,0.010607072,0.084194906,0.015953155,-0.011555981,-0.13959618,0.033996884,-0.07509344,0.06641197,-0.02514095,-0.00055413763,-0.0064352895,-0.0028