INSERT INTO "DocumentChunk" ("id", "workspaceId", "documentId", "heading", "content", "tokens", "embedding", "kind", "createdAt", "contextPrefix", "chunkType", "ordinal", "pageStart", "pageEnd", "chapter", "section", "subsection", "sectionPath", "sourceElementIds", "parentChunkId", "previousChunkId", "nextChunkId", "characterCount", "oversized", "contentHash", "parserVersion", "chunkerVersion", "embeddingModelVersion", "schemaVersion", "tokenEstimatorVersion", "embeddingDimensions", "indexVersion") VALUES ('chk-aba0193618899ddd2b18f302', 'bert-pre-training', 'doc_bert_2018', '3 BERT [6/13]', 'Unfortunately, standard conditional language models can only be trained left-to-right or right-to-left, since bidirec- tional conditioning would allow each word to in- directly “see itself”, and the model could trivially predict the target word in a multi-layered context. former is often referred to as a “Transformer encoder” while the left-context-only version is referred to as a “Transformer decoder”
since it can be used for text generation. In order to train a deep bidirectional representa- tion, we simply mask some percentage of the input tokens at random, and then predict those masked tokens. We refer to this procedure as a “masked LM” (MLM), although it is often referred to as a Cloze task in the literature (Taylor, 1953). In this case, the ﬁnal hidden vectors corresponding to the mask tokens are fed into an output softmax over the vocabulary, as in a standard LM.', 245, '[-0.017627826,0.040869765,-0.0015516944,-0.020925011,0.012931355,0.040359806,-0.005890276,-0.017223785,-0.013682781,-0.016613416,-0.013723923,0.009411079,0.08514184,-0.014682009,0.03662501,-0.054363385,0.08918495,0.016863316,-0.059959337,-0.015754478,0.06948637,0.0011261434,0.05879472,0.023741892,-0.012558886,0.01756273,-0.010799288,-0.04879799,0.0422245,-0.06245462,-0.0366766,0.09673858,0.029047905,-0.013171712,0.014386162,0.09359771,0.0014962956,0.056348912,-0.046405535,0.036500614,-0.04910753,-0.016653035,-0.025970059,0.009462634,-0.0043987273,-0.05107738,-0.061066516,0.022703303,-0.17173107,-0.039844878,-0.019611297,-0.03128796,-0.034869064,0.05560153,-0.02807938,-0.04700156,0.046282623,0.038835444,-0.006179711,-0.0054604164,-0.100811124,-0.01693585,-0.085677676,0.050271466,-0.00062291796,0.027075944,0.0046906294,-0.051287703,0.015177048,0.108317904,-0.021651197,-0.029171994,-0.035912476,0.03215763,0.014849586,0.06557439,0.08312317,-0.02560028,0.048667572,-0.13793917,0.122067064,-0.017347515,-0.03987421,-0.007981334,-0.054625906,0.009500506,0.01266862,-0.015252677,0.0048396816,-0.06345146,0.015071984,-0.115632206,0.029716285,0.066691965,-0.020546062,-0.0051035904,-0.010419303,0.017130397,0.05097986,0.17290954,-0.04339569,-0.009394293,-0.02708238,0.015755203,0.042808194,-0.04935504,0.011105461,-0.026564658,0.0066990666,-0.011541638,-0.04192402,0.008049961,-0.009633401,-0.027848534,-0.001772729,-0.079010524,0.021276457,0.0108673675,0.012635345,0.06826515,-0.027661871,0.007745726,0.0326670