INSERT INTO "DocumentChunk" ("id", "workspaceId", "documentId", "heading", "content", "tokens", "embedding", "kind", "createdAt", "contextPrefix", "chunkType", "ordinal", "pageStart", "pageEnd", "chapter", "section", "subsection", "sectionPath", "sourceElementIds", "parentChunkId", "previousChunkId", "nextChunkId", "characterCount", "oversized", "contentHash", "parserVersion", "chunkerVersion", "embeddingModelVersion", "schemaVersion", "tokenEstimatorVersion", "embeddingDimensions", "indexVersion") VALUES ('chk-588b013be8471dd11ea86b40', 'bert-pre-training', 'doc_bert_2018', '3 BERT [8/13]', 'We compare variations of this procedure in Appendix C.2. Task #2: Next Sentence Prediction (NSP) Many important downstream tasks such as Ques- tion Answering
(QA) and Natural Language Infer- ence (NLI) are based on understanding the rela- tionship between two sentences, which is not di- rectly captured by language modeling. In order to train a model that understands sentence rela- tionships, we pre-train for a binarized next sen- tence prediction task that can be trivially gener- ated from any monolingual corpus. Speciﬁcally, when choosing the sentences A and B for each pre- training example, 50% of the time B is the actual next sentence that follows A
(labeled as IsNext), and 50% of the time it is a random sentence from the corpus (labeled as NotNext). As we show in Figure 1, C is used for next sentence predic- tion (NSP).', 232, '[-0.030377772,0.054778203,0.013597553,-0.047943667,-0.018561866,-0.034247596,0.058111228,-0.009763127,-0.018741604,0.064620055,0.05278002,0.0092783645,0.04982886,0.016028624,0.0056982767,-0.05091393,0.029344706,0.04022431,-0.08482515,-0.016159615,0.034556516,0.021317497,0.020468,0.028024776,0.024265226,0.072556995,-0.039346326,-0.02444169,0.063663274,-0.07362786,0.0054736654,0.07850072,0.030000443,-0.030335838,-0.033168204,0.07723977,-0.021768305,0.034852415,-0.022370506,-0.015890572,-0.047854796,0.01304213,-0.06034433,0.01229574,0.048099983,-0.0072438973,-0.021031251,-0.0406303,-0.13018677,-0.028790968,-0.06465615,-0.07559837,-0.033903394,0.076216884,-0.0060960795,-0.03623508,0.05346748,-0.0070033404,-0.018484216,-0.012810091,-0.115707844,-0.02893923,-0.09239699,0.046230316,0.021920273,-0.019983824,0.008108659,-0.018214911,0.005795244,0.102067284,-0.021404963,-0.033905275,-0.06326054,0.008484052,0.010063786,-0.0032578674,0.06774102,0.085869715,0.010918141,-0.08004434,0.11935418,-0.060776915,0.017208932,0.021003557,0.0010140938,0.047121044,-0.012049933,0.021612085,0.035872042,-0.09119617,0.0445581,-0.04954921,0.027452366,0.022367595,0.03632053,0.019769197,-0.027918294,-0.0034687016,0.039549667,0.15164864,-0.036964916,0.027273968,-0.06730867,0.0058578677,0.01411977,-0.00094573566,0.04081165,0.005355857,-0.008356275,0.0011709913,-0.009989711,-0.019940527,0.027011752,-0.0211327,0.048711643,-0.07419527,0.09147764,-0.02480191,0.038721897,0.037555005,0.021573327,0.012346215,0.009821234,-0.027925983,0.074484475,-0.12817283,0.018484691,-0.08216716,-0.02193618,-0.031450793,0.10603849,-0.021533258,0.01871996,0.045351185,-0.012114834,-0.011867727,0.10056914,-0.02747988,-0.076104484,0.003908372,-0.052977834,0.1293692,0.07020528,0.066803955,-0.0008790155,0.0641193,-0.030183554,-0.041197874,0.0357918