INSERT INTO "DocumentChunk" ("id", "workspaceId", "documentId", "heading", "content", "tokens", "embedding", "kind", "createdAt", "contextPrefix", "chunkType", "ordinal", "pageStart", "pageEnd", "chapter", "section", "subsection", "sectionPath", "sourceElementIds", "parentChunkId", "previousChunkId", "nextChunkId", "characterCount", "oversized", "contentHash", "parserVersion", "chunkerVersion", "embeddingModelVersion", "schemaVersion", "tokenEstimatorVersion", "embeddingDimensions", "indexVersion") VALUES ('chk-82f3393ad4594462ccedc832', 'bert-pre-training', 'doc_bert_2018', '3 BERT [11/13]', '3.2 Fine-tuning BERT Fine-tuning is straightforward since the self- attention mechanism in the Transformer al- lows BERT to model many downstream tasks— whether they involve single text or text pairs—by swapping out the appropriate inputs and outputs. For applications involving text pairs, a common pattern is to independently encode
text pairs be- fore applying bidirectional cross attention, such as Parikh et al. (2016); Seo et al. (2017). BERT instead uses the self-attention mechanism to unify these two stages, as encoding a concatenated text pair with self-attention effectively includes bidi- rectional cross attention between two sentences. For each task, we simply plug in the task- speciﬁc inputs and outputs into BERT and ﬁne- tune all the parameters end-to-end.', 216, '[-0.031471867,0.020932617,-0.023867717,0.008642342,-0.051642276,0.026733462,0.034449056,-0.019274693,-0.040236793,0.009755243,0.03919867,-0.008238759,0.03829868,-0.026536306,0.038044535,-0.028121455,0.020485794,0.057538453,-0.08611953,-0.027154293,0.046035323,-0.039656337,0.025800234,0.006801055,-0.0023670238,0.040467136,-0.08376778,-2.9032146e-05,0.076296195,-0.12000409,0.05691179,0.105931245,0.04451401,-0.00031915744,0.0052570715,0.052962806,-0.03169353,0.016709486,-0.042279534,0.0017216717,-0.022499518,-0.011342137,-0.04313556,-0.07734849,0.021298269,-0.058911063,-0.10044131,0.033876162,-0.078556925,-0.0018106401,-0.047899466,-0.00025261941,-0.034762777,0.0695952,0.031671062,-0.08173675,0.01925899,0.0807552,-0.0037535871,0.040490795,-0.03375359,-0.016272245,-0.12724051,0.08753059,0.017268527,-0.0060082637,0.049684007,0.032111604,-0.05913531,0.03944824,-0.033686314,-0.0057937186,0.013385252,-0.020013276,0.010382769,0.007314962,-0.016678857,0.017648634,-0.04329373,-0.06877705,0.008131552,-0.045527894,0.009046769,0.051026102,0.01171998,0.024742765,-0.010035471,0.023475941,0.02144444,-0.06176238,-0.010389501,-0.07053627,0.0328966,0.043936394,-0.0026622145,-0.012741472,0.015819732,-0.015624672,0.027630271,0.15605207,-0.026330136,-0.0069991634,0.00906529,-0.0017271759,0.051394705,0.018993277,0.071091264,-0.05618607,-0.019224247,-0.023641523,-0.03026491,-0.010883417,0.0034043116,-0.03109696,0.00547569,-0.039728206,0.06641189,-0.038449552,0.094053134,0.071073405,-0.0025227587,0.03323712,0.0482957,0.036045607,0.088692255,-0.1248553