INSERT INTO "DocumentChunk" ("id", "workspaceId", "documentId", "heading", "content", "tokens", "embedding", "kind", "createdAt", "contextPrefix", "chunkType", "ordinal", "pageStart", "pageEnd", "chapter", "section", "subsection", "sectionPath", "sourceElementIds", "parentChunkId", "previousChunkId", "nextChunkId", "characterCount", "oversized", "contentHash", "parserVersion", "chunkerVersion", "embeddingModelVersion", "schemaVersion", "tokenEstimatorVersion", "embeddingDimensions", "indexVersion") VALUES ('chk-2e9166929273052618f7bdfd', 'bert-pre-training', 'doc_bert_2018', '3 BERT [12/13]', 'At the in- put, sentence A and sentence B from pre-training are
analogous to (1) sentence pairs in paraphras- ing, (2) hypothesis-premise pairs in entailment, (3) question-passage pairs in question answering, and (4) a degenerate text- ∅ pair in text classiﬁcation or sequence tagging. At the output, the token rep- resentations are fed into an output layer for token- level tasks, such as sequence tagging or question answering, and the [CLS] representation is fed into an output layer for classiﬁcation, such as en- tailment or sentiment analysis. Compared to pre-training,
ﬁne-tuning is rela- tively inexpensive. All of the results in the pa- per can be replicated in at most 1 hour on a sin- gle Cloud TPU, or a few hours on a GPU, starting from the exact same pre-trained model. 7 We de- scribe the task-speciﬁc details in the correspond- ing subsections of Section 4.', 243, '[0.03286428,0.031939916,0.014342969,0.011146354,-0.02991989,0.009079043,-0.013717294,0.014273962,-0.003071924,-0.0125853745,0.016407633,-0.018126484,0.055493664,0.0027124563,-0.009389528,-0.04315303,0.05905324,0.035729416,-0.024687883,-0.036894903,0.019687016,-0.00017533611,-0.004606335,0.014180915,0.024670731,-0.007058971,-0.06158438,-0.00814444,0.04296999,-0.13091162,-0.038707968,0.06086437,0.02371597,0.009108438,0.0053007714,0.08720226,0.034287393,0.06355639,-0.02029646,0.058301218,-0.039390355,-0.044747267,-0.02291529,-0.0028453872,0.03461546,-0.03221788,-0.04218452,-0.05326866,-0.13205762,-0.06973625,-0.019668376,-0.0090130335,-0.022512108,0.07530052,-0.0037680347,-0.047565904,0.07267917,-0.014460504,0.026149318,-0.020334458,-0.019055622,-0.011987969,-0.117352895,0.050707027,0.0066159577,-0.033088863,0.065536976,0.04200681,-0.021548955,0.09575654,-0.01565235,0.014431269,-0.023239804,0.03793109,0.007525445,0.05813942,0.0066420953,0.0011452013,0.02309504,-0.14264193,0.08414178,-0.034363203,-0.011626707,0.06023641,-0.012406521,0.0055874,-0.016761867,-0.0012483997,-0.015089775,-0.030055827,0.009189163,-0.12684365,0.021498105,0.046411075,0.023512276,-0.0072741252,0.002817664,0.00037966625,0.084090896,0.19074012,-0.032056913,0.061055124,-0.04515164,-0.050364234,-0.04166442,-0.026631678,0.05636965,-0.0109572485,-0.023122206,-0.0471122,-0.038259815,-0.027512053,-0.011653115,-0.032758195,0.02522993,-0.0815728,-0.0023684134,-0.02803771,0.023768615,0.06759643,0.026762273,0.0009675445,0.042242274,0.008770953,0.10801843,-0.14858429,0.0012900278,-0.08464228,-0.010963146,-0.06314925,0.10729969,0.018937172,-0.026177518,0.013353034,0.018193694,0.038273875,0.0405323,-0.056994326