INSERT INTO "DocumentChunk" ("id", "workspaceId", "documentId", "heading", "content", "tokens", "embedding", "kind", "createdAt", "contextPrefix", "chunkType", "ordinal", "pageStart", "pageEnd", "chapter", "section", "subsection", "sectionPath", "sourceElementIds", "parentChunkId", "previousChunkId", "nextChunkId", "characterCount", "oversized", "contentHash", "parserVersion", "chunkerVersion", "embeddingModelVersion", "schemaVersion", "tokenEstimatorVersion", "embeddingDimensions", "indexVersion") VALUES ('chk-cb3ea9e2d2469a10489d5580', 'bert-pre-training', 'doc_bert_2018', 'BERTBASE 84.4 88.4 86.7 92.7 88.5 [3/8]', 'For SQuAD it is intuitively clear that a LTR model will perform poorly at token predictions, since the token-level hidden states have no right- side context. In order to make a good faith at- tempt at strengthening the LTR system, we added a randomly initialized BiLSTM on top. This does signiﬁcantly improve results
on SQuAD, but the results are still far worse than those of the pre- trained bidirectional models. The BiLSTM hurts performance on the GLUE tasks. We recognize that it would also be possible to train separate LTR and RTL models and represent each token as the concatenation of the two mod- els, as ELMo does.', 174, '[-0.07050644,0.0153086055,-0.0041804556,-0.041267324,-0.03805794,0.020260138,-0.11571903,0.0441945,-0.006937419,-0.058098856,-0.02058542,0.04581374,0.08154174,-0.030545434,0.027523315,-0.041605502,0.037919655,0.032922674,-0.0836715,0.03179336,0.006386223,-0.07230721,0.015023147,0.015442316,0.048979968,-0.026375031,-0.000977295,-0.025357384,0.074448496,-0.14038388,-0.022196816,0.037127815,-0.017099326,-0.017918969,-0.03635374,0.065462336,0.0039126086,-0.003541909,-0.05749899,0.058831163,-0.047836047,0.034742717,-0.008963725,-0.019460667,0.009744923,-0.053364433,0.010270696,-0.025342826,-0.17835474,-0.0186482,-0.015914885,-0.016702134,-0.011748999,-0.03714546,-0.019084617,-0.032835472,0.02241273,0.03561636,-0.0329348,-0.04076264,-0.029290387,-0.02287377,-0.083201155,0.011018341,0.073124595,0.0018595572,0.036409672,-0.023116715,0.05656827,0.050966024,-0.0132161155,-0.015714394,-0.046534877,-0.061187346,-0.005979721,0.058342196,-0.022638274,0.027865017,0.07328043,-0.13681121,0.09302756,-0.08429514,-0.06144154,-0.0046071345,-0.0301299,-0.015430892,0.037160262,-0.039792005,-0.019825827,-0.034089528,0.10844184,-0.05274709,-0.020200165,0.0894598,0.068567164,0.054696187,-0.009791218,-0.0076741865,0.011745083,0.13856068,-0.07458607,0.02323685,-0.032893278,0.0119249,0.017688403,-0.070516564,0.01942829,-0.059946746,-0.031446498,0.02926909,0.049811564,-0.042342585,0.00225318,0.05125058,-0.009597891,-0.05358159,0.015565082,0.018730162,0.014951647,0.046880618,-0.012990643,-0.008364304,0.08643458,0.045986522,0.071092784,-0.083336435,-0.005122807,-0.052230682,-0.020878166,-0.08503986,0.09721608,-0.02246484,0.020160412,-0.0017017866,-0.026037045,0.03942972,0.052826203,-0.0