INSERT INTO "DocumentChunk" ("id", "workspaceId", "documentId", "heading", "content", "tokens", "embedding", "kind", "createdAt", "contextPrefix", "chunkType", "ordinal", "pageStart", "pageEnd", "chapter", "section", "subsection", "sectionPath", "sourceElementIds", "parentChunkId", "previousChunkId", "nextChunkId", "characterCount", "oversized", "contentHash", "parserVersion", "chunkerVersion", "embeddingModelVersion", "schemaVersion", "tokenEstimatorVersion", "embeddingDimensions", "indexVersion") VALUES ('chk-f3fdd349359467de49794a13', 'bert-pre-training', 'doc_bert_2018', 'BERTBASE 84.4 88.4 86.7 92.7 88.5 [6/8]', 'It has long been known that increasing the model size will lead to continual improvements on large-scale tasks such as machine translation and language modeling, which is demonstrated
by the LM perplexity of held-out training data shown in Table 6. However, we believe that this is the ﬁrst work to demonstrate convinc- ingly that scaling to extreme model sizes also leads to large improvements on very small scale tasks, provided that the model has been sufﬁ- ciently pre-trained. Peters et al. (2018b) presented mixed results on the downstream task impact of increasing the pre-trained bi-LM size from two to four layers and Melamud et al. (2016) men- tioned in passing that increasing
hidden dimen- sion size from 200 to 600 helped, but increasing further to 1,000 did not bring further improve- ments.', 224, '[-0.03925235,0.09777429,-0.008925569,-0.03774045,0.009725253,0.041055232,-0.10118293,0.044309165,0.00584221,0.018853536,-0.0126007125,0.07698667,0.07864917,-0.012964312,0.008189878,-0.05088763,0.010424339,0.0365552,-0.09368755,0.038347945,-0.0043450273,-0.053883344,0.050154008,-0.024469865,0.063281044,0.013490765,-0.05670079,-0.04512066,0.068189874,-0.12477239,0.0015819074,0.12059691,0.10902297,-0.070485204,0.020367252,0.09666495,0.030940264,0.027284473,-0.060755715,0.0600962,-0.05037864,0.0451836,0.024916267,-0.0064635393,0.033615693,-0.07545707,-0.019452404,-0.00023886134,-0.14190003,-0.031906065,-0.06267731,-0.05362854,-0.030392705,0.005758661,-0.014161198,-0.084755234,0.036103472,-0.012191771,-0.029100776,-0.0056032673,-0.049142536,0.016761545,-0.07328208,0.013962742,0.06375541,-0.0072083506,0.005793186,-0.025771694,0.015792435,0.12302533,-0.02901369,-0.01998533,-0.091146834,-0.062907435,-0.00075192313,0.05298342,-0.022206211,0.06863557,0.10153243,-0.12262979,0.09041673,-0.100577846,-0.075134344,0.004642401,-0.060260307,-0.039775442,-0.009176206,-0.01808128,0.018756388,-0.041530225,0.0822046,-0.027068611,-0.04345925,0.049886305,0.0009269659,0.025013607,-0.03542881,-0.04183612,0.03553697,0.15864389,-0.056161508,0.01362784,-0.0149183925,-0.001165709,-0.045349848,-0.03784616,0.042350926,-0.0029464283,-0.039403733,0.028355652,0.06810823,-0.008974031,-0.046546567,0.02328836,0.034195207,-0.04365764,0.031407494,-0.034091644,-0.024433926,0.086920716,-0.014537534,0.007877393,0.05808806,-0.027699713,0.05500978,-0.08221943,-0.042195067,-0.043331314,-0.017362522,-0.11129251,0.0804974,-0.009032036,0.018757127,0.014183848,-0.0092090005,0.012612655,0.09112841,-0.05526411,-0.028961668,0.09445454,0.005797106,0.091319725,0.08149537,0.08140937,-0.0036455898,0.09652226,-0.03846693,-0.03196914,0.05374181,-0.034069207,-0.013343031,-0.058789507,0.07537587,-0.06