INSERT INTO "DocumentChunk" ("id", "workspaceId", "documentId", "heading", "content", "tokens", "embedding", "kind", "createdAt", "contextPrefix", "chunkType", "ordinal", "pageStart", "pageEnd", "chapter", "section", "subsection", "sectionPath", "sourceElementIds", "parentChunkId", "previousChunkId", "nextChunkId", "characterCount", "oversized", "contentHash", "parserVersion", "chunkerVersion", "embeddingModelVersion", "schemaVersion", "tokenEstimatorVersion", "embeddingDimensions", "indexVersion") VALUES ('chk-c9bffb6933b33edf8a88292b', 'bert-pre-training', 'doc_bert_2018', '19–27. [2/3]', 'Masked LM and the Masking Procedure As- suming the unlabeled sentence is my dog is hairy, and during the random masking procedure we chose the 4-th token (which corresponding to hairy), our masking procedure can be further il- lustrated by • 80% of the time: Replace the word with the [MASK] token, e.g., my dog is hairy → my dog is [MASK] • 10% of the time: Replace the word with
a random word, e.g., my dog is hairy → my dog is apple • 10% of the time: Keep the word un- changed, e.g., my dog is hairy → my dog is hairy . The purpose of this is to bias the representation towards the actual observed word. The advantage of this procedure is that the Transformer encoder does not know which words it will be asked to predict or which have been re- placed by random words, so it is forced to keep a distributional contextual representation of ev- ery input token.', 240, '[-0.00065780047,0.04692125,0.026457893,0.022763131,-0.06405816,-0.0035086442,0.10411143,0.030896269,-0.006057586,0.038821626,-0.0034046243,-0.0756532,0.06108322,-0.061789818,0.0055606654,-0.013851958,0.033228893,0.03502658,-0.11453359,-0.036880035,0.05256273,0.01521964,-0.002739595,-0.01764928,-0.09218313,-0.025224604,-0.07384423,-0.002313843,0.017688502,-0.026370553,0.049766064,0.05305846,0.05491632,-0.0416315,-0.0013915277,0.08138582,0.0004362615,0.0018230046,-0.04423339,-0.011166595,-0.048360534,-0.05065647,-0.0061597847,-0.004455494,0.00050934637,0.017690873,-0.03280544,-0.015187587,-0.14603896,0.024238253,0.0043689157,-0.039197847,-0.0751004,0.06776864,-0.004514085,-0.016360821,0.11291116,0.078147344,-0.03754273,0.015753878,-0.04121032,-0.012738434,-0.1280196,0.064170234,0.0025961353,-0.065455005,-0.0040850635,-0.059153102,-0.08026295,0.100308016,0.040765397,-0.001907151,-0.041292552,0.010351199,0.062093876,0.006417151,0.06071899,0.01923376,-0.0052488944,-0.14946315,0.098477446,-0.02669997,-0.012521488,0.077474415,0.08451988,0.036942642,0.01789155,0.0125752855,-0.028489996,-0.005757162,0.00013572247,-0.07951356,0.027852088,0.03396385,0.040373303,-0.0024426861,-0.058874335,-0.006233401,-0.010260037,0.11416438,-0.024533479,0.048373215,-0.026589032,-0.05841399,0.004667914,-0.024366738,-0.011703686,-0.021429628,-0.020975685,0.03258658,-0.05497754,-0.010667971,-0.012471974,0.00998711,-0.00829094,-0.050237905,0.016527034,-0.054370616,0.042963598,0.026905976,0.035362944,0.04158031,-0.03