INSERT INTO "DocumentChunk" ("id", "workspaceId", "documentId", "heading", "content", "tokens", "embedding", "kind", "createdAt", "contextPrefix", "chunkType", "ordinal", "pageStart", "pageEnd", "chapter", "section", "subsection", "sectionPath", "sourceElementIds", "parentChunkId", "previousChunkId", "nextChunkId", "characterCount", "oversized", "contentHash", "parserVersion", "chunkerVersion", "embeddingModelVersion", "schemaVersion", "tokenEstimatorVersion", "embeddingDimensions", "indexVersion") VALUES ('chk-bbcce5003edd8691c23c15ab', 'bert-pre-training', 'doc_bert_2018', 'E1 E2  EN... [1/9]', '[MASK] are flight ##less birds [SEP] Label = NotNext A.2 Pre-training Procedure To generate each training input sequence, we sam- ple two spans of text from the corpus, which we refer to as “sentences” even though they are typ- ically much longer than single sentences (but can be shorter also). The ﬁrst sentence receives the A embedding and the second receives the B embed- ding. 50% of the time B is the actual next sentence that follows A and 50% of the time it is a random sentence, which is done
for the “next sentence pre- diction” task. They are sampled such that the com- bined length is≤ 512 tokens. The LM masking is applied after WordPiece tokenization with a uni- form masking rate of 15%, and no special consid- eration given to partial word pieces.', 212, '[0.016762545,0.072551586,0.03939826,0.011220116,-0.032612085,-0.005352664,0.044817287,0.00020582264,0.025560535,-0.029160496,0.0493779,-0.031807505,0.08155468,-0.009610716,-0.005427441,-0.030451583,0.06606519,0.023863055,-0.06574499,-0.06158307,0.07978965,0.0024544592,0.030501693,-0.002152935,-0.010902456,0.033031873,-0.105496325,-0.02711796,0.07637449,-0.03906646,-0.02786385,0.071210645,0.09254684,0.01096957,0.029242456,0.08309469,0.025366245,0.026914533,-0.05268499,0.063643225,-0.09987252,-0.0019272799,-0.030834688,0.05734793,0.010804774,-0.020235313,-0.08872543,-0.026243528,-0.15380965,-0.041454613,-0.00084971054,-0.039463874,-0.062103402,0.0683164,0.0064959032,-0.034497514,0.033999324,0.012298343,-0.023892865,0.017661506,-0.100160204,-0.007037814,-0.117708586,0.07977351,0.0010601872,0.014243231,0.045486487,-0.0062843137,-0.03880546,0.122343525,-0.009280585,-0.029272532,-0.09253457,0.026552912,-0.013091493,0.1089752,0.018995292,0.016831664,0.055808753,-0.13443136,0.08683229,-0.031195391,-0.03392923,0.01816763,-0.03608324,-0.021975392,0.0076964013,0.03337215,0.011889324,-0.030714778,-0.013315271,-0.12022973,0.00031912865,0.06818924,0.017489653,-0.046838526,0.0028550061,0.0076280516,0.055238314,0.13738519,-0.011240548,0.03737622,-0.050395314,-0.027592245,-0.023208318,0.051923465,0.011664472,-0.04694397,0.04264436,-0.021943685,-0.051583964,0.034640104,-0.00220308,-0.029968683,0.0075824307,-0.080623634,0.017604988,-0.023762634,0.05880055,0.10246107,0.0049100504,-0.0039327666,0.011639056,-0.011609965,0.10003874,-0.08230793,0.038696993,-0.06819862,0.004417606,-0.0541039,0.056787934,-0.049081538,0.010591505,0.087340675,0.022480845,0.0013139263,0.07424219,-0.0042087724,-0.0056026243,-0.005270233,-0.0624223