INSERT INTO "DocumentChunk" ("id", "workspaceId", "documentId", "heading", "content", "tokens", "embedding", "kind", "createdAt", "contextPrefix", "chunkType", "ordinal", "pageStart", "pageEnd", "chapter", "section", "subsection", "sectionPath", "sourceElementIds", "parentChunkId", "previousChunkId", "nextChunkId", "characterCount", "oversized", "contentHash", "parserVersion", "chunkerVersion", "embeddingModelVersion", "schemaVersion", "tokenEstimatorVersion", "embeddingDimensions", "indexVersion") VALUES ('chk-7b34f7317fe1c696d1ae24de', 'resnet-deep-residual-learning', 'doc_resnet_2015', '1 Introduction', 'Deep convolutional neural networks have led to a series of breakthroughs for image classification. Driven by the significance of depth, a question arises: Is learning better networks as easy as stacking more layers? When deeper networks start converging, a degradation problem has been exposed: with network depth increasing, accuracy becomes saturated and then degrades rapidly. Unexpectedly, such degradation is not caused by overfitting, and adding more layers to a suitably deep model leads to higher training error.\\n\\nWe present a deep residual learning framework. Instead of hoping every few stacked layers directly fit a desired underlying mapping, we explicitly let these layers fit a residual mapping.', 198, '[0.04286851,0.030993314,0.052544024,0.025482522,0.0012413482,-0.0027695543,-0.0735443,-0.004280536,-0.06314066,0.0007711423,-0.00072127226,0.05121841,0.08490972,-0.014893303,-0.00045457852,0.026924562,-0.019551877,-0.014231027,-0.107593246,0.029290592,-0.070209295,-0.05194043,0.035349004,0.0017428275,0.009653989,0.00047730474,-0.014265898,-0.012383793,0.10522308,-0.09236331,0.009525315,0.056738637,0.07337658,0.013034195,0.046666544,0.043809008,-0.002321299,0.03795712,-0.096535474,0.05252105,-0.04579202,0.010117316,-0.013125524,-0.045372844,0.024766715,-0.100141995,-0.0007998757,0.0067326534,-0.16818339,-0.07778576,-0.014712,-0.023461733,0.0020375755,-0.03