INSERT INTO "DocumentChunk" ("id", "workspaceId", "documentId", "heading", "content", "tokens", "embedding", "kind", "createdAt", "contextPrefix", "chunkType", "ordinal", "pageStart", "pageEnd", "chapter", "section", "subsection", "sectionPath", "sourceElementIds", "parentChunkId", "previousChunkId", "nextChunkId", "characterCount", "oversized", "contentHash", "parserVersion", "chunkerVersion", "embeddingModelVersion", "schemaVersion", "tokenEstimatorVersion", "embeddingDimensions", "indexVersion") VALUES ('chk-f2c2d6b32f9608ae3fe0970e', 'resnet-deep-residual-learning', 'doc_resnet_2015', 'Deep Residual Learning for Image Recognition > Extended Technical Details > Historical Breakthrough Metrics', '### Historical Breakthrough Metrics

